import re

def correct_bracketing(brackets: str) -> bool:
    opening_brackets = "<"
    closing_brackets = ">"

    if len(brackets) % 2 != 0:
        return False

    if not re.match(f"^{{({}^.{opening_brackets}{closing_brackets}*{closing_brackets}{opening_brackets}})*}$", brackets):
        return False

    stack = []
